import type { ExecutionStatus, ITaskData, ITaskStartedData, NodeConnectionType, WorkflowExecuteMode, WorkflowExecutionSource } from 'n8n-workflow';
export type ExecutionStarted = {
    type: 'executionStarted';
    data: {
        executionId: string;
        mode: WorkflowExecuteMode;
        source?: WorkflowExecutionSource;
        startedAt: Date;
        workflowId: string;
        workflowName?: string;
        retryOf?: string;
        flattedRunData: string;
    };
};
export type ExecutionWaiting = {
    type: 'executionWaiting';
    data: {
        executionId: string;
        source?: WorkflowExecutionSource;
    };
};
export type ExecutionFinished = {
    type: 'executionFinished';
    data: {
        executionId: string;
        workflowId: string;
        status: ExecutionStatus;
        source?: WorkflowExecutionSource;
    };
};
export type ExecutionRecovered = {
    type: 'executionRecovered';
    data: {
        executionId: string;
    };
};
export type AgentNodeCapability = {
    kind: 'tool';
    name: string;
} | {
    kind: 'skill';
    id: string;
    name?: string;
} | {
    kind: 'skill';
    id?: never;
    name: string;
};
export type AgentNodeProgress = {
    type: 'agentNodeProgress';
    data: {
        executionId: string;
        nodeId: string;
        nodeName: string;
        runIndex: number;
        itemIndex: number;
        sequenceNumber: number;
        toolCallId: string;
        capability: AgentNodeCapability;
        status: 'running' | 'succeeded' | 'failed';
    };
};
export type NodeExecuteBefore = {
    type: 'nodeExecuteBefore';
    data: {
        executionId: string;
        nodeName: string;
        sequenceNumber: number;
        data: ITaskStartedData;
    };
};
export type NodeExecuteAfter = {
    type: 'nodeExecuteAfter';
    data: {
        executionId: string;
        nodeName: string;
        sequenceNumber: number;
        data: Omit<ITaskData, 'data'>;
        itemCountByConnectionType: Partial<Record<NodeConnectionType, number[]>>;
    };
};
export type NodeExecuteAfterData = {
    type: 'nodeExecuteAfterData';
    data: {
        executionId: string;
        nodeName: string;
        data: ITaskData;
        itemCountByConnectionType: NodeExecuteAfter['data']['itemCountByConnectionType'];
    };
};
export type ExecutionPushMessage = ExecutionStarted | ExecutionWaiting | ExecutionFinished | ExecutionRecovered | AgentNodeProgress | NodeExecuteBefore | NodeExecuteAfter | NodeExecuteAfterData;
